use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let mut nums = input.as_array().unwrap();
    let mut zero_index = 0;
    for i in 0..nums.len() {
        if nums[i].is_i64() && nums[i].as_i64().unwrap() == 0 {
            zero_index = i;
        }
    }
    let mut result = Value::Array::new();
    let mut zero_index = 0;
    for i in 0..nums.len() {
        if nums[i].is_i64() && nums[i].as_i64().unwrap() != 0 {
            result.push(Value::from(nums[i].as_i64().unwrap()));
        } else {
            if zero_index < nums.len() {
                result.push(Value::from(nums[i].as_i64().unwrap()));
                zero_index += 1;
            }
        }
    }
    result
}
